{"code": "import subprocess
import os

# Try to initialize and pull LFS files
os.chdir('data')
try:
    result = subprocess.run(['git', 'lfs', 'install'], capture_output=True, text=True)
    print(f"Git LFS install: {result.stdout}")
    if result.stderr:
        print(f"Errors: {result.stderr}")
except Exception as e:
    print(f"Error installing git lfs: {e}")

try:
    result = subprocess.run(['git', 'lfs', 'pull'], capture_output=True, text=True, timeout=30)
    print(f"Git LFS pull: {result.stdout}")
    if result.stderr:
        print(f"Errors: {result.stderr}")
except Exception as e:
    print(f"Error pulling git lfs: {e}")

# Check if git lfs is available
try:
    result = subprocess.run(['git-lfs', '--version'], capture_output=True, text=True)
    print(f"Git LFS version: {result.stdout}")
except Exception as e:
    print(f"Git lfs not available: {e}")

os.chdir('..')"}

