{"code": "import re
import numpy as np
import tensorflow as tf

# Test count_data_items function
TRAINING_FILENAMES = tf.io.gfile.glob("data/tfrecords-jpeg-192x192/train/*.tfrec")
def count_data_items(filenames):
    n = [int(re.compile(r"-([0-9]*)\.").search(filename).group(1)) for filename in filenames]
    return np.sum(n)

print("Training filenames:", TRAINING_FILENAMES[:3])
print("Count from filename:", count_data_items(TRAINING_FILENAMES))"}

